const horario = '14:45';

const partes = horario.split(':');
console.log(`Horas: ${partes[0]}`);
console.log(`Minutos: ${partes[1]}`);

const anotacao = 'ovos; leite; café; pão';

const itens = anotacao.split('; ');
console.log(`Itens: ${itens.length}`);
console.log(`Primeiro: ${itens[0]}`);
console.log(`Último: ${itens[itens.length - 1]}`);

const treinos = '30,45,20,60,25';

const minutos = treinos.split(',');
const total = minutos.reduce((soma, minuto) => soma + Number(minuto), 0);
const media = total / minutos.length;

console.log(`Total: ${total} minutos`);
console.log(`Média por dia: ${media} minutos`);
